    if d.get('type')=='subscribe':subs[cid]=core.event_head(cid);await ws.send_json({'type':'subscribed','channel_id':cid,'head_event_id':subs[cid]})
    elif d.get('type')=='resume':subs[cid]=int(d.get('since_event_id',0));await ws.send_json({'type':'resumed','channel_id':cid,'head_event_id':core.event_head(cid)})
 finally:task.cancel()
